tag=v0.5.0; sha=b4ec9a4fae219ce0b6e93fcbcec96f874ec20aa8; for d in p12f675 p16f628a p16f877a p16f887 p16f1937 p18f4550; do gh api "repos/apojomovsky/epic-cc/contents/crates/device/devices/$d.toml?ref=$tag" --jq .content | base64 -d > "$d.toml"; done; TAG=$tag SHA=$sha python3 - <<'EOF'
import json, os, tomllib
path = "scripts/osc_snapshot.json"
snapshot = json.load(open(path))
devices = {}
for name in ["p12f675", "p16f628a", "p16f877a", "p16f887", "p16f1937", "p18f4550"]:
    doc = tomllib.load(open(f"{name}.toml", "rb"))
    for field in doc["config"]["fields"]:
        if field["name"] == "osc" or "FOSC" in field.get("aliases", []):
            words = {v["name"].upper() for v in field["values"]}
            words |= {a.upper() for v in field["values"] for a in v.get("aliases", [])}
            devices[name] = sorted(words)
snapshot["_header"]["epic_cc_tag"] = os.environ["TAG"]
snapshot["_header"]["epic_cc_sha"] = os.environ["SHA"]
snapshot["devices"] = devices
json.dump(snapshot, open(path, "w"), indent=2, sort_keys=True)
open(path, "a").write("\n")
EOF
